    for (const d of defs) {
      occs.push({ range: locate(d.sym.line, d.sym.name), symbol: d.symbol, roles: ROLE_DEFINITION });
    }
    const callerFamily = familyOf2(f.lang);
    const bind = binder.forFile(f);
